/* @autogenerated */
import { Component, DestroyRef, effect, inject, input, signal, untracked } from '@angular/core';
import { Observable, Subscription, take } from 'rxjs';
import { DownloadBlob } from '@shared/data/repository/provider/repository-provider.interface';

/**
 * Imagen de un campo fichero de la fila (el icono de una fila o de una tarjeta). `file` es el valor del campo y
 * `download` el `download<Campo>` del repositorio. Si no hay fichero o no se puede descargar no muestra nada.
 * Es redonda, como los avatares; `--list-view-image-radius` cambia el radio.
 */
@Component({
  selector: 'list-view-image',
  template: `@if (url(); as src) {
    <img class="list-view-image" [src]="src" alt="" />
  }`,
  styles: [
    ':host { display: contents; }',
    '.list-view-image { width: 100%; height: 100%; object-fit: cover; border-radius: var(--list-view-image-radius, 50%); }',
  ],
})
export class ListViewImageComponent {
  file = input<string | null | undefined>();
  download = input.required<(url?: string) => Observable<DownloadBlob> | null>();

  readonly url = signal<string | null>(null);
  private subscription?: Subscription;

  constructor() {
    effect(() => {
      const file = this.file();
      const download = this.download();
      // Solo dependen de file y download: la URL anterior se libera sin seguirla
      untracked(() => {
        this.release();
        const source = file ? download(file) : null;
        this.subscription = source?.pipe(take(1)).subscribe({
          next: (blob) => this.url.set(URL.createObjectURL(blob.data)),
          error: () => this.url.set(null),
        });
      });
    });
    inject(DestroyRef).onDestroy(() => this.release());
  }

  private release() {
    this.subscription?.unsubscribe();
    const current = this.url();
    if (current) {
      URL.revokeObjectURL(current);
      this.url.set(null);
    }
  }
}
